for k,v in S.items():
    ph,no,q,an,ex=D[k]
    assert len(no)==len(v['nouns']),k
    assert len(v['recall'])==3+len(ex),(k,v['recall'])
    assert [p['text'] for p in v['phrases']]==v['recall'][:3],k
    out[k]={"phrases":ph,"nouns":no,"question":q,"answer":an,"captions":{},"recall":ph+ex}
assert set(D)==set(S)
json.dump(out,open(R+'de/sk.json','w'),ensure_ascii=False,indent=1)
